@replay : ∀ {σ : Type u_2} (j : σ) (d e : σ →₀ ℕ),
  hasseCoeff d (e + Finsupp.single j 1 + d) * (e j + 1) =
    (d j + 1) * hasseCoeff (d + Finsupp.single j 1) (e + Finsupp.single j 1 + d)

@replay : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] {d a : σ →₀ ℕ},
  (∀ j ∈ d.support, a j = 0) →
    ∀ (c : R) (g : MvPolynomial σ R), (hasseDeriv d) ((monomial a) c * g) = (monomial a) c * (hasseDeriv d) g

@Polynomial.hasseDeriv_mul : ∀ {R : Type u_3} [inst : Semiring R] (k : ℕ) (f g : Polynomial R),
  (Polynomial.hasseDeriv k) (f * g) =
    ∑ ij ∈ Finset.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g

@LinearMap.map_smul : ∀ {R : Type u_3} {M : Type u_4} {M₂ : Type u_5} [inst : Semiring R] [inst_1 : AddCommMonoid M]
  [inst_2 : AddCommMonoid M₂] [inst_3 : Module R M] [inst_4 : Module R M₂] (fₗ : M →ₗ[R] M₂) (c : R) (x : M),
  fₗ (c • x) = c • fₗ x

@hasseDeriv_single_aeval_X : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] (j : σ) (n : ℕ) (f : Polynomial R),
  (hasseDeriv (Finsupp.single j n)) ((Polynomial.aeval (X j)) f) =
    (Polynomial.aeval (X j)) ((Polynomial.hasseDeriv n) f)

@Polynomial.lhom_ext' : ∀ {R : Type u_1} [inst : Semiring R] {M : Type u_2} [inst_1 : AddCommMonoid M]
  [inst_2 : Module R M] {f g : Polynomial R →ₗ[R] M},
  (∀ (n : ℕ), f ∘ₗ Polynomial.monomial n = g ∘ₗ Polynomial.monomial n) → f = g

@Polynomial.aeval_monomial : ∀ {R : Type u_1} {A : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A]
  [inst_2 : Algebra R A] (x : A) {n : ℕ} {r : R},
  (Polynomial.aeval x) ((Polynomial.monomial n) r) = (algebraMap R A) r * x ^ n
